// 模板题：@EDIT{params} 参数接口
interface EditParam {
  line?: number;   // 最大行数（0 或缺省=不限，1=单行）
  min?: number;     // 最小长度（-1 或缺省=不限）
  max?: number;     // 最大长度（-1 或缺省=不限）
}

// 解析 @EDIT{params} 中的参数字符串
const parseEditParams = (paramsStr: string): EditParam => {
  const result: EditParam = {};
  if (!paramsStr) return result;
  for (const part of paramsStr.split(",")) {
    const eqIdx = part.indexOf("=");
    if (eqIdx < 0) continue;
    const key = part.substring(0, eqIdx).trim().toLowerCase();
    const val = parseInt(part.substring(eqIdx + 1), 10);
    if (isNaN(val)) continue;
    if (key === "line") result.line = val;
    else if (key === "min") result.min = val;
    else if (key === "max") result.max = val;
  }
  return result;
};

// 模板题：存储每个可编辑区的用户输入（zone 编辑内容）
// key = zone index, value = 用户填写的内容
const zoneEdits = ref<Map<number, string>>(new Map());

// 从模板 + zoneEdits 重建最终提交代码（去掉 @EDIT{} 标记，替换为用户内容）
const rebuildFinalCode = (template: string): string => {
  const re = /@EDIT\{([^}]*)\}/gi;
  let idx = 0;
  return template.replace(re, (match) => {
    const content = zoneEdits.value.get(idx) ?? "";
    idx++;
    return content;
  });
};

// 解析模板中的 @EDIT{} 占位标记（纯字符串解析，不依赖 Monaco model）
const parseCurrentEditZones = (template: string): { offset: number; length: number; params: EditParam }[] => {
  const re = /@EDIT\{([^}]*)\}/gi;
  const zones: { offset: number; length: number; params: EditParam }[] = [];
  let m: RegExpExecArray | null;
  while ((m = re.exec(template)) !== null) {
    zones.push({
      offset: m.index,
      length: m[0].length,
      params: parseEditParams(m[1]),
    });
  }
  return zones;
};

// 获取模板中 @EDIT{} 的原始位置（纯 offset 信息，供闭包内快速使用）
const getTemplateZones = (template: string): { offset: number; length: number; paramsStr: string }[] => {
  const re = /@EDIT\{([^}]*)\}/gi;
  const zones: { offset: number; length: number; paramsStr: string }[] = [];
  let m: RegExpExecArray | null;
  while ((m = re.exec(template)) !== null) {
    zones.push({ offset: m.index, length: m[0].length, paramsStr: m[1] });
  }
  return zones;
};

// 根据原始模板 + zoneEdits 重建编辑器内容（已填写区域替换，未填写保留 @EDIT{}）
const rebuildEditorContent = (template: string): string => {
  const re = /@EDIT\{([^}]*)\}/gi;
  let idx = 0;
  return template.replace(re, (match) => {
    const content = zoneEdits.value.get(idx);
    idx++;
    return content != null && content !== "" ? content : match;
  });
};

// 尝试从缓存的最终代码中提取用户内容恢复到 zoneEdits
// 返回 true 表示缓存与模板匹配，已成功恢复
const tryRestoreFromCache = (cachedCode: string, template: string): boolean => {
  const tplZones = getTemplateZones(template);
  if (tplZones.length === 0) return false;

  // 提取模板中的不可编辑段（@EDIT{} 之外的部分）
  const tplImmutables: string[] = [];
  let cur = 0;
  for (const z of tplZones) {
    if (cur < z.offset) {
      tplImmutables.push(template.substring(cur, z.offset));
    }
    cur = z.offset + z.length;
  }
  if (cur < template.length) {
    tplImmutables.push(template.substring(cur));
  }

  if (tplImmutables.length === 0) {
    // 整个模板就是 @EDIT{...}，没有不可编辑段 → 整段缓存就是用户内容
    if (tplZones.length === 1) {
      zoneEdits.value.set(0, cachedCode.trimEnd());
      return true;
    }
    return false;
  }

  // 在缓存代码中按顺序匹配不可编辑段
  let matchCur = 0;
  const matchPositions: { start: number; end: number }[] = [];
  for (const imm of tplImmutables) {
    const idx = cachedCode.indexOf(imm, matchCur);
    if (idx < 0) return false;
    matchPositions.push({ start: idx, end: idx + imm.length });
    matchCur = idx + imm.length;
  }

  // 提取用户在不可编辑段之间的代码（对应每个 @EDIT{} 区域）
  // zone i 的内容 = immutable[i] 结束 到 immutable[i+1] 开始 之间的部分
  for (let i = 0; i < tplZones.length; i++) {
    const userContent = cachedCode.substring(
      matchPositions[i].end,
      matchPositions[i + 1]?.start ?? cachedCode.length,
    );
    if (userContent) {
      zoneEdits.value.set(i, userContent);
    }
  }

  return true;
};

