  const templateKeys = Object.keys(problemData.value.template);
  return languageOptions.value.filter((opt) => {
    if (opt.value === undefined) return false;
    const langKey = GetHighlightKeyByJudgeLanguage(opt.value);
    return templateKeys.includes(langKey);
  });
});
