const loadDailyData = async () => {
  clearDailyTimer();
  isDailyProblem.value = false;
  const res = await GetProblemDaily(dailyId);
  if (res.code !== 0) {
    return;
  }
  isDailyProblem.value = true;
  const daily = res.data.problem_daily;
  problemKey = daily.problem_key;
  dailySolution.value = daily.solution;
  dailyCode.value = daily.code;

  const serverTime = new Date(res.data.time);
  serverTimeOffset = serverTime.getTime() - new Date().getTime();
  const localTime = new Date(serverTime.getTime());
  const year = localTime.getFullYear();
  const month = String(localTime.getMonth() + 1).padStart(2, "0");
  const day = String(localTime.getDate()).padStart(2, "0");
  const timeId = `${year}-${month}-${day}`;
  if (dailyId === timeId) {
    // 如果是当日的每日一题，则获取距离18点的倒计时
    const duration = serverTime.getHours() * 60 * 60 + serverTime.getMinutes() * 60 + serverTime.getSeconds();
    const duration18 = 18 * 60 * 60;
    if (duration < duration18) {
      dailySolutionUnlockCountdown.value = duration18 - duration;
    } else {
      dailySolutionUnlockCountdown.value = -1;
    }
    dailyCodeUnlockCountdown.value = 24 * 60 * 60 - duration;
  }
  if (dailySolutionUnlockCountdown.value >= 0 || dailyCodeUnlockCountdown.value >= 0) {
    createDailyTimer();
  }
};

const createDailyTimer = () => {
  if (dailyUpdateProgressTimer.value) {
    clearInterval(dailyUpdateProgressTimer.value);
  }
  dailyUpdateProgressTimer.value = setInterval(() => {
    const solutionUnlock = dailySolutionUnlockCountdown.value <= 0;

    const serverTime = new Date(new Date().getTime() + serverTimeOffset);
    const duration = serverTime.getHours() * 60 * 60 + serverTime.getMinutes() * 60 + serverTime.getSeconds();
    const duration18 = 18 * 60 * 60;
    if (duration < duration18) {
      dailySolutionUnlockCountdown.value = duration18 - duration;
    } else {
      dailySolutionUnlockCountdown.value = -1;
    }
    dailyCodeUnlockCountdown.value = 24 * 60 * 60 - duration;
    if ((!solutionUnlock && dailySolutionUnlockCountdown.value <= 0) || dailyCodeUnlockCountdown.value <= 0) {
      loadDailyData();
    }
  }, 1000);
};

const clearDailyTimer = () => {
  if (dailyUpdateProgressTimer.value) {
    clearInterval(dailyUpdateProgressTimer.value);
    dailyUpdateProgressTimer.value = null;
  }
};

// 拖动调整高度相关方法
const startResize = (event: MouseEvent) => {
  isResizing.value = true;
  startY.value = event.clientY;

  // 获取当前编辑器高度
  const editorElement = codeEditRefZen.value;
  if (editorElement) {
    startEditorHeight.value = editorElement.offsetHeight;
  }

  // 添加全局事件监听
  document.addEventListener("mousemove", handleResize);
  document.addEventListener("mouseup", stopResize);
  document.body.style.cursor = "ns-resize";
  document.body.style.userSelect = "none";
};

const handleResize = (event: MouseEvent) => {
  if (!isResizing.value) return;

  const deltaY = event.clientY - startY.value;
  const newHeight = startEditorHeight.value + deltaY;

  // 设置最小/最大高度限制
  const minHeight = 100;
  const maxHeight = window.innerHeight - 250;
  const clampedHeight = Math.max(minHeight, Math.min(maxHeight, newHeight));

  const editorElement = codeEditRefZen.value;
  if (editorElement) {
    editorElement.style.height = `${clampedHeight}px`;
  }
};

const stopResize = () => {
  isResizing.value = false;

  // 移除全局事件监听
  document.removeEventListener("mousemove", handleResize);
  document.removeEventListener("mouseup", stopResize);
  document.body.style.cursor = "";
  document.body.style.userSelect = "";

  // 持久化编辑器高度
  const editorElement = codeEditRefZen.value;
  if (editorElement) {
    localStorage.setItem("problem_editor_height", String(editorElement.offsetHeight));
  }

  // 重新布局编辑器
  if (codeEditor) {
    codeEditor.layout();
  }
};

// 左右拖动调整宽度相关方法
const startHSplit = (event: MouseEvent) => {
  isHSplitting.value = true;
  startX.value = event.clientX;

  // 通过编辑器容器的父元素获取代码列
  const codeCol = codeEditRefZen.value?.parentElement as HTMLElement | null;
  if (codeCol) {
    startCodeWidth.value = codeCol.offsetWidth;
  }

  document.addEventListener("mousemove", handleHSplit);
  document.addEventListener("mouseup", stopHSplit);
  document.body.style.cursor = "ew-resize";
  document.body.style.userSelect = "none";
};

const handleHSplit = (event: MouseEvent) => {
  if (!isHSplitting.value) return;

  const deltaX = event.clientX - startX.value;
  const newWidth = startCodeWidth.value + deltaX;

  // 设置最小/最大宽度限制
  const minWidth = 200;
  const maxWidth = window.innerWidth - 300;
  const clampedWidth = Math.max(minWidth, Math.min(maxWidth, newWidth));
  codeColWidth.value = clampedWidth;
};

const stopHSplit = () => {
  isHSplitting.value = false;

  document.removeEventListener("mousemove", handleHSplit);
  document.removeEventListener("mouseup", stopHSplit);
  document.body.style.cursor = "";
  document.body.style.userSelect = "";

  // 持久化代码区宽度
  if (codeColWidth.value !== null) {
    localStorage.setItem("problem_code_col_width", String(codeColWidth.value));
  }

  // 重新布局编辑器（宽度变化后需要重新 layout）
  nextTick(() => {
    if (codeEditor) {
      codeEditor.layout();
    }
  });
};

