let resizeObserver: ResizeObserver | null = null;

// 拖动调整高度相关变量
const isResizing = ref(false);
const startY = ref(0);
const startEditorHeight = ref(0);

// 拖动调整左右宽度相关变量（编程模式下代码区与题目描述区之间的分隔条）
const isHSplitting = ref(false);
const startX = ref(0);
const startCodeWidth = ref(0);
const codeColWidth = ref<number | null>(null); // 代码区宽度（像素），null 表示使用默认 CSS 宽度

// 当前生效的代码编辑器容器：
// - 移动端：统一 Tab 布局，始终用「代码」Tab 的 codeEditRefZen
// - 桌面端：编程模式用 codeEditRefZen，否则用右侧栏的 codeEditRef
const getActiveCodeContainer = () =>
  (isMobile.value || isZenMode.value) ? codeEditRefZen : codeEditRef;

// 在当前容器中（重新）创建 Monaco 编辑器，并重建 resizeObserver
const recreateEditor = () => {
  if (resizeObserver) {
    resizeObserver.disconnect();
    resizeObserver = null;
  }
  const container = getActiveCodeContainer();
  // 进入桌面端编程模式时，恢复保存的编辑器高度
  if (isZenMode.value && !isMobile.value && container.value) {
    const savedEditorHeight = localStorage.getItem("problem_editor_height");
    if (savedEditorHeight) {
      container.value.style.height = `${savedEditorHeight}px`;
    }
  }
  handleResetCode(container);
  if (container.value) {
    resizeObserver = new ResizeObserver(() => {
      if (codeEditor) {
        codeEditor.layout();
      }
    });
    resizeObserver.observe(container.value);
  }
};

// footer 显隐：移动端此页隐藏以腾出空间；桌面端仅编程模式隐藏
const applyFooter = () => {
  footerStyleStore.setFooterShow(isMobile.value ? false : !isZenMode.value);
};

// 编程模式切换（仅桌面端有此按钮；移动端统一 Tab 布局不再使用）
const handleZenMode = () => {
  isZenMode.value = !isZenMode.value;
  localStorage.setItem("problem_zen_mode", isZenMode.value ? "1" : "0");
  applyFooter();
  // 模式切换后容器可能改变（桌面端 normal↔zen），需重新创建编辑器
  nextTick(() => {
    recreateEditor();
  });
};

