const fetchProblemData = async () => {
  contestProblems.value = [];

  let res = await GetProblem(problemKey, contestId, problemIndex.value);

  if (res.code !== 0) {
    problemLoading.value = false;
    ShowErrorTips(globalProperties, res.code);
    await router.push({ name: "problem" });
    return;
  }

  res.data.problem.tags = [];
  if (res.data.tags) {
    res.data.tags.forEach((tag: ProblemTag) => {
      tagsMap[tag.id] = tag;
    });
    res.data.problem.tags = res.data.tags.map((tag: ProblemTag) => tag.id);
  }

  problemData.value = ParseProblem(res.data.problem, tagsMap);

  problemSpaceType.value = res.data.problem.space_type ?? SpaceType.Normal;

  problemId = problemData.value.id;
  problemKey = problemData.value.key;

  webStyleStore.setTitle(problemData.value.title + " - " + webStyleStore.getRouteTitle);

  if (contestId) {
    res = await GetContestProblems(contestId);
    if (res.code === 0) {
      res.data.problems.sort((a: number, b: number) => a - b);
      contestProblems.value = res.data.problems;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  }

  const originOj = problemData.value.originOj;
  languageOptions.value = GetSubmitLanguages(originOj) as { label: string; value: JudgeLanguage | undefined }[];

  // 从本地缓存读取selectLanguage
  const localSelectLanguageStr = localStorage.getItem("problem_select_language");
  if (localSelectLanguageStr) {
    // 转换为JudgeLanguage类型并判断是否在过滤后的语言选项中
    const parsedLanguage = parseInt(localSelectLanguageStr);
    if (!isNaN(parsedLanguage) && filteredLanguageOptions.value.some((lang) => lang.value === parsedLanguage)) {
      selectLanguage.value = parsedLanguage as JudgeLanguage;
    }
  }

  // 模板题 + 没有选中任何语言 → 自动选第一个有模板的语言
  if (!selectLanguage.value && problemData.value?.template && Object.keys(problemData.value.template).length > 0) {
    if (filteredLanguageOptions.value.length > 0) {
      selectLanguage.value = filteredLanguageOptions.value[0].value as unknown as JudgeLanguage;
    }
  }

  problemDescription.value = problemData.value.description as string;
  await nextTick(() => {
    if (!codeEditor) {
      recreateEditor();
    }
    problemLoading.value = false;
  });
};

const handleClickCrawl = async () => {
  const originOj = problemData.value?.originOj;
  const originId = problemData.value?.originId;
  if (!originOj || !originId) {
    return;
  }

  try {
    problemCrawlLoading.value = true;
    const res = await PostProblemCrawl(originOj, originId);
    if (res.code === 0) {
      await fetchProblemData();
      ShowTextTipsInfo(globalProperties, "更新成功");
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (error) {
    ShowTextTipsError(globalProperties, "更新失败，请稍后再试");
  } finally {
    problemCrawlLoading.value = false;
  }
};

// 处理上一题
const handlePrevProblem = async () => {
  if (!problemId) {
    ShowTextTipsError(globalProperties, "题目ID无效");
    return;
  }

  try {
    problemNavigating.value = true;
    const res = await GetPrevProblem(problemId);
    if (res.code === 0 && res.data.problem) {
      await router.push({
        name: "problem-detail",
        params: {
          problemKey: res.data.problem.key,
        },
      });
    } else {
      ShowTextTipsInfo(globalProperties, "已经是第一题");
    }
  } catch (error) {
    ShowTextTipsError(globalProperties, "获取上一题失败，请稍后再试");
  } finally {
    problemNavigating.value = false;
  }
};

// 处理下一题
const handleNextProblem = async () => {
  if (!problemId) {
    ShowTextTipsError(globalProperties, "题目ID无效");
    return;
  }

  try {
    problemNavigating.value = true;
    const res = await GetNextProblem(problemId);
    if (res.code === 0 && res.data.problem) {
      await router.push({
        name: "problem-detail",
        params: {
          problemKey: res.data.problem.key,
        },
      });
    } else {
      ShowTextTipsInfo(globalProperties, "已经是最后一题");
    }
  } catch (error) {
    ShowTextTipsError(globalProperties, "获取下一题失败，请稍后再试");
  } finally {
    problemNavigating.value = false;
  }
};

const handleSubmitCode = async () => {
  const selectLanguageValue = parseInt(selectLanguage.value);
  if (!IsJudgeLanguageValid(selectLanguageValue)) {
    ShowTextTipsError(globalProperties, "请选择所编写的语言");
    return;
  }
  let code = codeEditor?.getValue();
  if (!code) {
    ShowTextTipsError(globalProperties, "请输入所需提交的代码");
    return;
  }

  // 模板题：从原始模板 + zoneEdits 重建最终代码（去掉 @EDIT{} 标记）
  const currentTemplate = getTemplateForCurrentLanguage();
  if (currentTemplate) {
    code = rebuildFinalCode(currentTemplate);
  }
  if (!problemKey && (!contestId || !problemIndex.value)) {
    ShowTextTipsError(globalProperties, "问题标识无效");
    return;
  }

  problemSubmitting.value = true;

  try {
    const res = await PostJudgeJob(problemId, contestId, problemIndex.value, selectLanguageValue, code, isPrivate.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }

    ShowTextTipsInfo(globalProperties, "提交成功，正在跳转到详情页面");

    const statusId = res.data.id;

    // 提交成功后清空代码缓存
    localStorage.removeItem(getCacheKey());

    if (contestId) {
      await router.push({
        name: "contest-judge-detail",
        params: {
          contestId: contestId,
          judgeId: statusId,
        },
      });
    } else {
      await router.push({
        name: "judge-detail",
        params: {
          judgeId: statusId,
        },
      });
    }
  } finally {
    problemSubmitting.value = false;
  }
};

const handleResetCode = async (containerRef?: Ref<HTMLElement | null>) => {
  // 模板题专用：模板原文从服务端拉取，写入编辑器并锁定不可编辑区
  const codeTemplate = getTemplateForCurrentLanguage() ?? "";

  const isContainReadOnly = !!codeTemplate;

  // 尝试从缓存恢复（缓存中存的是最终代码，不含 @EDIT{}）
  const cached = localStorage.getItem(getCacheKey());
  zoneEdits.value.clear();

  let oldCodeValue: string;
  if (isContainReadOnly) {
    if (cached && tryRestoreFromCache(cached, codeTemplate)) {
      // 缓存有效：重建包含 @EDIT{} 标记的编辑器内容（已填区域显示代码，未填保留标记）
      oldCodeValue = rebuildEditorContent(codeTemplate);
    } else {
      // 缓存无效或不存在：用模板原文
      oldCodeValue = codeTemplate;
    }
  } else {
    oldCodeValue = cached ?? "";
  }

  // 动态加载 monaco 核心和当前选中语言的语法高亮
  const langKey = GetHighlightKeyByJudgeLanguage(
    parseInt(selectLanguage.value) as JudgeLanguage
  );
  editorLoading.value = true;
  try {
    monaco = await loadMonacoWithLanguage(langKey);

    // 如果已有 editor，先销毁旧实例
    if (codeEditor) {
      codeEditor.dispose();
    }

    // 确定使用哪个容器
    const targetContainer = containerRef ? containerRef.value : codeEditRef.value;

    // 确保目标容器不为null
    if (targetContainer) {
    // 清空现有内容
    targetContainer.innerHTML = "";

    // 创建编辑器容器
    const editorContainer = document.createElement("div");
    editorContainer.style.width = "100%";
    editorContainer.style.height = "100%";

    codeEditor = monaco.editor.create(editorContainer, {
      value: oldCodeValue,
      language: langKey || "cpp",
      minimap: { enabled: true },
      colorDecorators: true,
      readOnly: isContainReadOnly,
      theme: "vs-dark",
      automaticLayout: true,
      glyphMargin: isContainReadOnly,
      // 使用 keep 模式，粘贴时不主动调整缩进，保持用户复制的原始内容
      autoIndent: "keep",
    });

    targetContainer.appendChild(editorContainer);

    // 编辑器 DOM 已挂载，关闭加载状态
    nextTick(() => {
      editorLoading.value = false;
    });

    // 修复粘贴代码时出现递增制表符的问题（桌面端 + 移动端通用）
    //
    // 根因：从 md-preview 代码块复制后粘贴到 Monaco 编辑器时，粘贴内容可能
    // 通过以下路径处理：
    //   a) 原生 paste 事件 → Monaco 内部 type 路径（桌面端 paste handler）
    //   b) beforeinput(insertFromPaste) → 被 Monaco 转成 type 路径
    //   c) beforeinput(insertText) → 逐行作为"键入"处理（某些平台/浏览器）
    //
    // 路径 (c) 最为恶劣：粘贴内容被拆成逐行 insertText，Monaco 用 cursor.type
    // 逐字符处理，每个 \n 触发 EnterOperation，autoIndent:'keep' 复制"当前行"
    // 缩进到下一行。叠加后形成递增制表符，每行比上一行多一个 \t。
    //
    // 路径 (a) 和 (b) 在某些浏览器（如 Firefox）中 e.data 为 null，导致拦截器
    // 静默跳过，同样回落为逐行处理。
    //
    // 方案（双层防御）：
    // 1. paste 事件（捕获阶段）：桌面端首选，读 clipboardData，preventDefault +
    //    stopPropagation，用 executeEdits 原子替换选区。
    // 2. beforeinput 事件（捕获阶段）：移动端 / Firefox 兜底，检测 insertFromPaste
    //    或 insertFromPasteAsQuotation。有 data 同步插入，无 data 异步读 clipboard；
    //    始终 preventDefault。
    //
    // 均走 ReplaceCommand 路径，不触发 autoIndent，粘贴结果 = 剪贴板原样。
    nextTick(() => {
      const textarea = editorContainer.querySelector("textarea");
      if (!textarea) return;

      // ── 第一层防御：paste 事件（桌面端最可靠）──
      textarea.addEventListener(
        "paste",
        (e: ClipboardEvent) => {
          if (!codeEditor) return;
          if (codeEditor.getOption(monaco.editor.EditorOption.readOnly)) return;
          const text = e.clipboardData?.getData("text/plain");
          if (!text) return;
          e.preventDefault();
          e.stopPropagation();
          const selection = codeEditor.getSelection();
          if (!selection) return;
          codeEditor.executeEdits("paste", [
            {
              range: selection,
              text,
              forceMoveMarkers: true,
            },
          ]);
        },
        true,
      );

      // ── 第二层防御：beforeinput（移动端 / Firefox data=null 兜底）──
      textarea.addEventListener(
        "beforeinput",
        (e: InputEvent) => {
          if (!codeEditor) return;
          if (codeEditor.getOption(monaco.editor.EditorOption.readOnly)) return;
          if (e.inputType !== "insertFromPaste" && e.inputType !== "insertFromPasteAsQuotation") {
            return;
          }
          // 无论 data 是否存在，一律阻止默认行为，防止回落为逐行 type 处理
          e.preventDefault();
          e.stopPropagation();
          if (e.data) {
            const selection = codeEditor.getSelection();
            if (!selection) return;
            codeEditor.executeEdits("paste-beforeinput", [
              {
                range: selection,
                text: e.data,
                forceMoveMarkers: true,
              },
            ]);
          } else {
            // data 为 null（如 Firefox）：异步从 clipboard 读取
            navigator.clipboard.readText().then((clipText) => {
              if (!clipText || !codeEditor) return;
              const selection = codeEditor.getSelection();
              if (!selection) return;
              codeEditor.executeEdits("paste-clipboard", [
                {
                  range: selection,
                  text: clipText,
                  forceMoveMarkers: true,
                },
              ]);
            }).catch(() => {});
          }
        },
        true,
      );
    });

    // 确保编辑器正确布局
    nextTick(() => {
      if (codeEditor && targetContainer) {
        codeEditor.layout();
      }
    });
  } else {
    // 目标容器不存在，无法挂载编辑器，关闭加载状态
    editorLoading.value = false;
  }

  // 确保codeEditor不为null再进行后续操作
  if (codeEditor) {
    const model = codeEditor.getModel();
    let decorationIds: string[] = [];

    // ──────────────────────────────────────────────────────────
    // 模板题「只读骨架 + 弹窗编辑」方案
    //
    // 整体方案：主编辑器显示包含 @EDIT{params} 占位标记的模板原文，
    // 标记被视觉隐藏，替换为📝图标。点击标记 → 打开弹窗编辑器。
    // 用户输入存储在 zoneEdits 中，确认时替换 @EDIT{} 标记。
    // 提交时从 zoneEdits 重建最终代码（不含 @EDIT{} 标记）。
    // ──────────────────────────────────────────────────────────

    // ---- 解析 @EDIT{params} 占位标记 ----
    interface EditZone {
      offset: number;
      line: number;
      col: number;
      length: number;
      params: EditParam;
      markerRange: monaco.Range;  // @EDIT{...} 标记在编辑器中的范围
    }

    function parseEditZones(): EditZone[] {
      if (!model) return [];
      const content = model.getValue();
      const markerRe = /@EDIT\{([^}]*)\}/gi;
      const zones: EditZone[] = [];
      let m: RegExpExecArray | null;
      while ((m = markerRe.exec(content))) {
        const off = m.index;
        const before = content.substring(0, off);
        const line = (before.match(/\n/g) || []).length + 1;
        const col = off - (before.lastIndexOf("\n") + 1) + 1;
        const paramsStr = m[1];
        const params = parseEditParams(paramsStr);
        zones.push({
          offset: off,
          line,
          col,
          length: m[0].length,
          params,
          markerRange: new monaco.Range(line, col, line, col + m[0].length),
        });
      }
      markerRe.lastIndex = 0;
      return zones;
    }

    // ---- 定位已填写的用户代码区域 ----
    // 在重建后的编辑器内容中，扫描出每段不在 template 中的"用户代码"范围
    interface FilledZoneInfo {
      zoneIndex: number;
      range: monaco.Range; // 在编辑器中可直接选中的代码范围
    }

    function findFilledZones(editorContent: string, template: string): FilledZoneInfo[] {
      const zones = getTemplateZones(template);
      const filled: FilledZoneInfo[] = [];
      // 基于模板原始 offset 逐段计算编辑器中对应代码的位置偏移
      for (let i = 0; i < zones.length; i++) {
        const content = zoneEdits.value.get(i);
        if (!content || content.trim() === "") continue;
        filled.push({
          zoneIndex: i,
          range: locateUserCodeInEditor(editorContent, zones, i, content),
        });
      }
      return filled;
    }

    // 在已重建的 editorContent 中定位第 zoneIndex 段用户代码的 Monaco Range
    function locateUserCodeInEditor(
      editorContent: string,
      tplZones: { offset: number; length: number }[],
      zoneIndex: number,
      userContent: string,
    ): monaco.Range {
      // 计算这段用户代码在编辑器中的偏移
      // 思路：模拟 rebuildEditorContent 对前面 zone 的替换，逐段累积偏移
      let shift = 0;
      for (let i = 0; i <= zoneIndex; i++) {
        const originalOffset = tplZones[i].offset;
        const posInEditor = originalOffset + shift;
        if (i === zoneIndex) {
          // 将 posInEditor 转为 Monaco (line, col) —— 1-based
          const before = editorContent.substring(0, posInEditor);
          const beforeLines = before.match(/\n/g) || [];
          const line = beforeLines.length + 1;
          const lastNewline = before.lastIndexOf('\n');
          const col = lastNewline < 0 ? posInEditor + 1 : posInEditor - lastNewline;
          const contentLines = userContent.split('\n');
          const endLine = line + contentLines.length - 1;
          const endCol = contentLines.length === 1
            ? col + userContent.length
            : contentLines[contentLines.length - 1].length + 1;
          return new monaco.Range(line, col, endLine, endCol);
        }
        // 前面区域在当前编辑器中的实际长度 vs 模板中标记长度
        const userLen = zoneEdits.value.get(i)?.length;
        if (userLen != null && userLen > 0) {
          shift += userLen - tplZones[i].length;
        }
        // 未填写：编辑器里是 @EDIT{...} 原始标记，长度不变，shift += 0
      }
      return new monaco.Range(1, 1, 1, 1);
    }

    // ---- 视觉装饰 ----
    function updateDecorations() {
      if (!model) return;
      const editorContent = model.getValue();
      const decs: monaco.editor.IModelDeltaDecoration[] = [];

      // 解析 editorContent 中剩余的 @EDIT{}（未填写的区域）
      const unfilledZones = parseEditZones();

      // 未填写的占位标记：隐藏标记文字 + 显示 ✏️ 徽章
      for (let i = 0; i < unfilledZones.length; i++) {
        const zone = unfilledZones[i];
        decs.push({
          range: zone.markerRange,
          options: {
            inlineClassName: "edit-marker-hidden",
            after: { content: " ✏️ #" + (i + 1), inlineClassName: "edit-zone-badge" },
          },
        });
      }

      // 已填写的代码区域：绿色高亮
      const filledZones = findFilledZones(editorContent, currentTemplate);
      for (const fz of filledZones) {
        decs.push({
          range: fz.range,
          options: {
            className: "edit-zone-filled-highlight",
          },
        });
      }

      // 只读行装饰：不含任何可编辑内容的行（不含未填的 @EDIT{} 行，也不含已填区域的代码行）
      const editableLineSet = new Set<number>();
      for (const zone of unfilledZones) {
        editableLineSet.add(zone.line);
      }
      for (const fz of filledZones) {
        for (let ln = fz.range.startLineNumber; ln <= fz.range.endLineNumber; ln++) {
          editableLineSet.add(ln);
        }
      }

      const totalLines = model.getLineCount();
      let readonlyStart = 0;
      for (let ln = 1; ln <= totalLines; ln++) {
        if (!editableLineSet.has(ln)) {
          if (readonlyStart === 0) readonlyStart = ln;
        } else {
          if (readonlyStart > 0) {
            decs.push({
              range: new monaco.Range(readonlyStart, 1, ln - 1, 1),
              options: {
                isWholeLine: true,
                className: "readonly-line-enhanced",
                glyphMarginClassName: "readonly-glyph",
              },
            });
            readonlyStart = 0;
          }
        }
      }
      if (readonlyStart > 0) {
        decs.push({
          range: new monaco.Range(readonlyStart, 1, totalLines, 1),
          options: {
            isWholeLine: true,
            className: "readonly-line-enhanced",
            glyphMarginClassName: "readonly-glyph",
          },
        });
      }

      decorationIds = model.deltaDecorations(decorationIds, decs);
    }

    // ---- 弹窗编辑逻辑 ----
    const currentTemplate = codeTemplate; // 保存原始模板引用

    const openEditZone = (zoneIndex: number) => {
      editingZoneIndex.value = zoneIndex;
      editZoneDialogVisible.value = true;

      // 获取当前编辑器中该区域已有的内容
      const tplZones = getTemplateZones(currentTemplate);
      const existingContent = zoneEdits.value.get(zoneIndex) ?? "";
      const zoneParams = parseEditParams(tplZones[zoneIndex]?.paramsStr ?? "");

      nextTick(() => {
        if (!editZoneDialogRef.value) return;
        editZoneDialogRef.value.innerHTML = "";
        editZoneEditor = monaco.editor.create(editZoneDialogRef.value, {
          value: existingContent,
          language: "cpp",
          theme: "vs-dark",
          minimap: { enabled: false },
          automaticLayout: true,
          lineNumbers: "on",
          scrollBeyondLastLine: false,
          wordWrap: "on",
          fontSize: 14,
        });

        if (zoneParams.line === 1) {
          editZoneEditor.addCommand(monaco.KeyCode.Enter, () => {});
        }

        editZoneEditor.focus();
      });
    };

    confirmEditZone = () => {
      if (editingZoneIndex.value < 0 || !codeEditor || !model || !editZoneEditor || !isContainReadOnly) return;

      const newContent = editZoneEditor.getValue();
      const tplZones = getTemplateZones(currentTemplate);
      const zone = tplZones[editingZoneIndex.value];
      if (!zone) return;
      const params = parseEditParams(zone.paramsStr);

      // 约束校验
      if (params.line && params.line > 0) {
        const lineCount = (newContent.match(/\n/g) || []).length + 1;
        if (lineCount > params.line) {
          ShowTextTipsError(globalProperties, `内容不能超过 ${params.line} 行（当前 ${lineCount} 行）`);
          return;
        }
      }
      if (params.min !== undefined && params.min >= 0 && newContent.length < params.min) {
        ShowTextTipsError(globalProperties, `内容长度不能少于 ${params.min}`);
        return;
      }
      if (params.max !== undefined && params.max >= 0 && newContent.length > params.max) {
        ShowTextTipsError(globalProperties, `内容长度不能超过 ${params.max}`);
        return;
      }

      // 保存编辑，重建编辑器内容
      zoneEdits.value.set(editingZoneIndex.value, newContent);
      const newEditorContent = rebuildEditorContent(currentTemplate);

      codeEditor.updateOptions({ readOnly: false });
      codeEditor.setValue(newEditorContent);
      codeEditor.updateOptions({ readOnly: true });

      // 保存最终代码到 localStorage（不含 @EDIT{} 标记的纯用户代码）
      localStorage.setItem(getCacheKey(), rebuildFinalCode(currentTemplate));

      updateDecorations();
      closeEditZoneDialog();
    };

    cancelEditZone = () => {
      closeEditZoneDialog();
    };

    const closeEditZoneDialog = () => {
      editZoneDialogVisible.value = false;
      editingZoneIndex.value = -1;
      if (editZoneEditor) {
        editZoneEditor.dispose();
        editZoneEditor = null;
      }
    };

    // ---- 主编辑器事件 ----
    if (isContainReadOnly) {
      updateDecorations();

      // 记住 zone 编号→ Monacorig 标记行和列的映射，防止 confirm 后重新查找找不到
      // （编辑后的代码中 @EDIT{} 已消失，只能用模板元数据推导）

      // 点击事件：✏️ 徽章(未填) / 绿色区域(已填) → 打开弹窗
      codeEditor.onMouseDown((e: monaco.editor.IEditorMouseEvent) => {
        const pos = e.target.position;
        if (!pos) return;

        // 1. 先检查是否点击了未填的 @EDIT{} 标记（视觉隐藏，显示 ✏️ 徽章）
        const unfilledZones = parseEditZones();
        for (let i = 0; i < unfilledZones.length; i++) {
          const z = unfilledZones[i];
          // +1 覆盖 after 装饰的 ✏️ 徽章
          if (pos.lineNumber === z.line && pos.column >= z.col && pos.column < z.col + z.length + 1) {
            openEditZone(i);
            return;
          }
        }

        // 2. 检查是否点击了已填代码区（绿色高亮区域）
        const editorContent = model.getValue();
        const filledZones = findFilledZones(editorContent, currentTemplate);
        for (const fz of filledZones) {
          if (fz.range.containsPosition(pos)) {
            openEditZone(fz.zoneIndex);
            return;
          }
        }
      });

      // 光标自动跳到第一个可编辑区
      const zones = parseEditZones();
      if (zones.length > 0) {
        codeEditor.revealLineInCenter(zones[0].line);
      }
    }

    // 自动保存
    if (model) {
      model.onDidChangeContent(() => {
        if (isContainReadOnly) {
          // 模板题：始终存储不含 @EDIT{} 的最终代码
          if (currentTemplate) {
            localStorage.setItem(getCacheKey(), rebuildFinalCode(currentTemplate));
          }
          updateDecorations();
        } else if (codeEditor) {
          // 非模板题：原样存储
          localStorage.setItem(getCacheKey(), codeEditor.getValue());
        }
      });
    }
  }
  } catch (err) {
    console.error("Failed to load monaco editor:", err);
    editorLoading.value = false;
  }
};

const handleClickResetCode = () => {
  // 清空本地缓存和模板题的编辑状态
  localStorage.removeItem(getCacheKey());
  zoneEdits.value.clear();
  handleResetCode(getActiveCodeContainer());
};

const handlePrivateChanged = (value: boolean): void => {
  isPrivate.value = value;
  // 保存到本地存储
  localStorage.setItem("problem_submit_private", value ? "1" : "0");
};

const onSelectLanguageChanged = async (value: JudgeLanguage): Promise<void> => {
  // 切语言前先保存当前编辑器内容到"旧语言"的缓存
  if (codeEditor) {
    const currentTemplate = getTemplateForCurrentLanguage();
    if (currentTemplate) {
      // 模板题：始终存储不含 @EDIT{} 的最终代码
      localStorage.setItem(getCacheKey(), rebuildFinalCode(currentTemplate));
    } else {
      const current = codeEditor.getValue();
      if (current) {
        localStorage.setItem(getCacheKey(), current);
      }
    }
  }
  // 同步选中的语言（getCacheKey / getTemplateForCurrentLanguage 都依赖它）
  selectLanguage.value = value as unknown as JudgeLanguage;

  // 动态加载新选择语言的语法高亮支持
  const langKey = GetHighlightKeyByJudgeLanguage(value);
  if (monaco && langKey) {
    await loadMonacoLanguage(langKey);
  }

  // 重新初始化编辑器：新语言下，缓存优先；缓存为空时用模板
  await handleResetCode(getActiveCodeContainer());
  // 持久化
  localStorage.setItem("problem_select_language", String(value));
};

// 测试运行相关方法
const handleRunCode = async () => {
  const code = codeEditor?.getValue();
  if (!code) {
    ShowTextTipsError(globalProperties, "请输入需要运行的代码");
    return;
  }

  // 验证语言选择
  const selectLanguageValue = parseInt(selectLanguage.value);
  if (!IsJudgeLanguageValid(selectLanguageValue)) {
    ShowTextTipsError(globalProperties, "请选择所编写的语言");
    return;
  }

  isRunning.value = true;
  runResult.value = "正在提交到远程测试...";
  runStatus.value = runStatusDefault;

  try {
    // 提交运行请求
    const runResponse = await PostRunCode({
      code: code,
      input: runTestData.value,
      language: selectLanguageValue,
    });

    if (runResponse.code !== 0) {
      ShowErrorTips(globalProperties, runResponse.code);
      const [found, realTips] = GetText(runResponse.code);
      runResult.value = found ? realTips : "运行失败";
      isRunning.value = false;
      return;
    }

    const runId = runResponse.data;

    // 开始定时获取运行状态
    runTimer.value = setInterval(async () => {
      try {
        const stateResponse = await GetRunCodeState(runId);

        if (stateResponse.code === 0) {
          const { status, content } = stateResponse.data;
          if (IsRunStatusRunning(status)) {
            // 正在运行，显示结果
            runResult.value = content;
            runStatus.value = GetRunStatusStr(status);
          } else {
            // 运行完成，停止定时器
            if (runTimer.value) {
              clearInterval(runTimer.value);
              runTimer.value = null;
            }
            isRunning.value = false;
            runStatus.value = GetRunStatusStr(status);
            runResult.value = content;
          }
        } else {
          // 获取状态失败
          if (runTimer.value) {
            clearInterval(runTimer.value);
            runTimer.value = null;
          }
          isRunning.value = false;
          ShowErrorTips(globalProperties, stateResponse.code);
          runResult.value = "获取运行状态失败";
        }
      } catch (error) {
        console.error("获取运行状态错误:", error);
        if (runTimer.value) {
          clearInterval(runTimer.value);
          runTimer.value = null;
        }
        isRunning.value = false;
        runResult.value = "网络错误，请重试";
      }
    }, 1000);
  } catch (error) {
    console.error("提交运行请求错误:", error);
    isRunning.value = false;
    runResult.value = "提交运行请求失败";
    ShowTextTipsError(globalProperties, "提交运行请求失败");
  }
};

// 清理定时器（组件销毁时调用）
const clearRunTimer = () => {
  if (runTimer.value) {
    clearInterval(runTimer.value);
    runTimer.value = null;
  }
};

onMounted(async () => {
  // 读取保存的代码区宽度
  const savedWidth = localStorage.getItem("problem_code_col_width");
  if (savedWidth) {
    codeColWidth.value = parseInt(savedWidth, 10);
  }

  // 读取编程模式设置（仅桌面端生效；移动端统一为 Tab 布局，忽略此开关）
  isZenMode.value = localStorage.getItem("problem_zen_mode") === "1";
  applyFooter();

  watchHandle = watch(
    () => route.params,
    async () => {
      isDailyProblem.value = false;
      // 判断是否直接通过路由参数指定了problemKey
      isDirectProblemKey.value = false;
      if (Array.isArray(route.params.problemKey)) {
        problemKey = route.params.problemKey[0];
        isDirectProblemKey.value = !!problemKey;
      } else {
        problemKey = route.params.problemKey;
        isDirectProblemKey.value = !!problemKey;
      }
      if (Array.isArray(route.params.dailyId)) {
        dailyId = route.params.dailyId[0];
      } else {
        dailyId = route.params.dailyId;
      }
      if (Array.isArray(route.params.contestId)) {
        contestId = Number(route.params.contestId[0]);
      } else {
        contestId = Number(route.params.contestId);
      }
      // 如果有dailyId或contestId，则不是直接指定problemKey
      if (dailyId || contestId) {
        isDirectProblemKey.value = false;
      }
      if (!problemKey && dailyId) {
        problemLoading.value = true;
        await loadDailyData();
        problemLoading.value = false;
      }
      if (!problemKey) {
        if (contestId) {
          if (Array.isArray(route.params.problemIndex)) {
            problemIndex.value = parseInt(route.params.problemIndex[0]);
          } else {
            problemIndex.value = parseInt(route.params.problemIndex);
          }
          if (!problemIndex.value) {
            ShowTextTipsError(globalProperties, "题目不存在");
            await router.push({
              name: "contest-detail",
              params: { contestId: contestId },
            });
            return;
          }
        } else {
          ShowTextTipsError(globalProperties, "题目不存在");
          if (dailyId) {
            await router.push({ name: "problem-daily-list" });
          } else {
            await router.push({ name: "problem" });
          }
        }
      }
      isContestProblem.value = !!contestId;

      problemLoading.value = true;

      await fetchProblemData();
    },
    { immediate: true }
  );

  // 从本地存储读取提交代码私有选项
  const localIsPrivate = localStorage.getItem("problem_submit_private");
  if (localIsPrivate === "1") {
    isPrivate.value = true;
  } else {
    isPrivate.value = false;
  }
});

onBeforeUnmount(() => {
  if (watchHandle) {
    watchHandle();
    watchHandle = null;
  }

  // 清理拖动事件监听器
  if (isResizing.value) {
    stopResize();
  }
  if (isHSplitting.value) {
    stopHSplit();
  }

  // 清理运行定时器
  clearRunTimer();

  clearDailyTimer();

  footerStyleStore.$patch({
    showFooter: true,
  });
});
</script>

